"""December planning after reading all eighteen poems; preserves historical issue identity."""
import json,hashlib
from pathlib import Path
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[3];K=Path(__file__).resolve().parent;B=K/'batches/edition-14';S=R/'projects/site';now=datetime.now(timezone.utc).isoformat()
q=json.loads((K/'queue.json').read_text());assert q['active_batch'] is None;assert not (B/'batch.json').exists();B.mkdir(parents=True,exist_ok=True)
rows=[(334, 'the-pickle-jar-remembered', 'The pickle jar remembered', 'The fragrance poem lets smell restore childhood and family care. A close glimpse into a half-used mango pickle jar recalls the grandmother’s preparation without assembling every food and memory or inventing family portraits.', 'Horizontal 3:2 warm loose gouache and colored-pencil study, oblique overhead crop of an ordinary wide-mouthed clear glass jar of raw mango pickle on a plain kitchen work surface. The jar is cropped partly by the left edge; irregular green-gold mango pieces sit partly submerged in reddish mustard-spice oil, some hidden behind glass. Its plain lid lies just partly visible beyond the upper crop. Broad quiet warm off-white surface to right. No arranged raw ingredients, spoon bouquet, label, writing, floral cloth or polished product photography. Jar has believable curved refraction and small uneven traces of oil near inner rim, not dirt. Soft side daylight; the closeness of remembered taste and care.'), (335, 'colours-returned-to-childhood', 'Colours returned to childhood', 'The working child finds his lost childhood in a borrowed kaleidoscope. Show the small optical experience from inside the toy rather than fabricate Dukhiram’s face, body or labour scene.', 'Horizontal 3:2 abstract but optically plausible view through a simple worn-in-use toy kaleidoscope. A small circular aperture slightly off-center reveals three mirror sectors repeating irregular translucent red, amber and blue glass fragments into a triangular family of reflections, with uneven clear gaps. The rim and outer field remain soft dark charcoal and warm paper, with much quiet space; crop the circle gently at one edge if natural. The glass fragments differ in size and overlap with transmitted daylight, some out of focus. No jewel-like luxury gemstones, perfect sacred mandala, stars, hearts, glowing cosmic background, text, child, face or hand. Modest crayon and watercolor interpretation of an optical memory; vivid central surprise with understated surroundings. Repetition only where the mirror geometry causes it.'), (339, 'woolens-in-the-winter-sun', 'Woolens in the winter sun', 'The winter poem welcomes sun and the thought of bringing out woolens. A partly unfolded shawl on an ordinary outdoor chair suggests work paused and warmth sought, without repeating a generic steaming teacup.', 'Horizontal 3:2 loose graphite and pale watercolor courtyard fragment. An ordinary straight-backed wooden chair at right is cropped slightly by the frame, with a muted rust wool shawl casually folded over its back and one end hanging under gravity toward the seat. Winter sunlight enters from upper left, warms the wool and plain pale ground, casts one coherent soft chair shadow to lower right. Large unadorned open courtyard space at left, no architecture landmark, plants, tea, book, decorations or people. Fabric weight and weave suggested selectively, not micro-detailed, no frayed decorative distress. A bright welcoming ordinary morning, not a styled lifestyle advertisement.')]
items=[]
for pid,ident,title,reason,scene in rows:
 p=S/f'content/editions/issue-14/poem-{pid}.json';d=json.loads(p.read_text());snapshot=B/f'poem-{pid}.json';snapshot.write_bytes(p.read_bytes())
 prompt=f'Use case: illustration-story. Original horizontal 3:2 literary artwork for Kabita Live Issue14. Human Natural in Poetic Natural mode. Preserve the selected expressive medium; a painted interpretation, never documentary evidence.\nEmotional anchor: {reason}\nScene and medium: {scene}\nAnti-optimization checks: avoid staged object display, equal detail everywhere, mechanically repeated shapes, theatrical lighting and cosmetic distress. Material contact, geometry and illumination must make sense. Preserve quiet negative space and emotional ambiguity. No identifiable real people, portraits, readable text, signature, logos or watermark. No people, portraits or documentary location claims. Opaque ivory-paper background.\nPoem {d["title"]} by {d["author"]}; source read fully, use as context only, never render the words:\n{d["text"]}\n'
 pp=B/f'{ident}-prompt.txt';pp.write_text(prompt)
 items.append(dict(id=ident,edition=14,poem_id=pid,title=title,rationale=reason,status='pending',prompt=str(pp.relative_to(R)),poem_source=str(p.relative_to(R)),poem_evidence=str(snapshot.relative_to(R)),poem_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),output=f'kb/artifacts/artwork/edition-art-rollout-2026-10-04/edition-14/{ident}/v1.png',attempts=[],medium_label={334:'gouache and colored pencil',335:'crayon and watercolor',339:'graphite and watercolor'}[pid],independent=False))
plain=[{'poem_id': 322, 'rationale': 'The poem’s criticism of appetite, power and missing divinity remains a text-led argument, without inventing a god’s likeness.', 'status': 'pending'}, {'poem_id': 329, 'rationale': 'The desired companion is complex and forceful; preserve the direct address without supplying an idealized woman or literal poison/explosives.', 'status': 'pending'}, {'poem_id': 333, 'rationale': 'The ethical debate among epic figures needs its verbal tensions intact; avoid a fabricated mythological tableau or simplifying it to a fallen leaf.', 'status': 'pending'}]
for p in (S/'content/editions/issue-14').glob('poem-*.json'):(B/p.name).write_bytes(p.read_bytes())
b=dict(edition=14,status='planned',created_at=now,poems_read=sorted(json.loads(p.read_text())['id'] for p in (S/'content/editions/issue-14').glob('poem-*.json')),direction='December gives memory three sensory scales: the taste held in a pickle jar, the small kaleidoscope where childhood returns, and wool warmed by winter sun. A close food-memory crop, an optical abstraction and a spacious courtyard fragment vary visual language. Criticism of power, the complicated companion and mythic ethics remain text-led.',items=items,text_led=plain,independent=False)
(B/'batch.json').write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n');ed=next(x for x in q['editions'] if x['edition']==14);ed.update(status='planned',artworks=[i['id'] for i in items],text_led=[i['poem_id'] for i in plain],batch=str((B/'batch.json').relative_to(R)),direction=b['direction']);q['active_batch']=dict(id='edition-14',owner='current-chat-assistant',started_at=now,status='running');q['updated_at']=now;(K/'queue.json').write_text(json.dumps(q,ensure_ascii=False,indent=2)+'\n')
